function beautySum(s) {
  const n = s.length;
  let total = 0;

  for (let start = 0; start < n; start++) {
    const count = new Array(26).fill(0);
    for (let end = start; end < n; end++) {
      count[s.charCodeAt(end) - 97]++;
      let most = 0;
      let least = n;
      for (const c of count) {
        if (c > 0) {
          most = Math.max(most, c);
          least = Math.min(least, c);
        }
      }
      total += most - least;
    }
  }
  return total;
}

