function beautySum(s) {
  let sum = 0;
  for (let i = 0; i < s.length; i++)
    for (let j = i + 1; j <= s.length; j++) {
      const freq = new Map();
      for (const ch of s.slice(i, j)) freq.set(ch, (freq.get(ch) || 0) + 1);
      const values = [...freq.values()];
      sum += Math.max(...values) - Math.min(...values);
    }
  return sum;
}

