function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const kinds = 1 + Math.floor(rand() * (rand() < 0.5 ? 4 : 26));
  const n = size === 'large' ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * kinds)];
  return [s];
}
